[5804]={["aftermath"]="Dithers prepared to secure it with a special solvent and complete the key's power.",["atomIDs"]={"5804:description:1-67","5804:description:70-158","5804:description:161-254","5804:description:259-366","5804:description:369-428","5804:description:433-466","5804:objective:1-108"},["endingAtomIDs"]={"5804:completion:1-16","5804:completion:23-93","5804:completion:95-180","5804:completion:185-227","5804:completion:229-397","5804:completion:402-434"},["opening"]="The final key component was held at Andorhal's heart. Dithers required the former schoolmaster's scarab, whose authority could be mounted onto the forged bones.",["pending"]="{actor} planned to bring the scarab to Dithers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Araj's signet to the Bulwark.",["sourceHash"]="a4478aeb675bfdda5d96c0dbed3d733a181c2af8ac36855e7758563c13e60b5a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5805]={["aftermath"]="Merissa offered a choice of companions; the source account did not identify which one the recipient selected.",["atomIDs"]={"5805:description:1-33","5805:description:38-180","5805:description:183-280","5805:description:285-343","5805:objective:1-54"},["endingAtomIDs"]={"5805:completion:1-34","5805:completion:36-115"},["opening"]="A Northshire gift voucher could be presented to Merissa Stilwell. Her offer concerned a traveling companion, a welcome distinct from the guard's work around the abbey.",["pending"]="{actor} would present the Northshire voucher to Merissa.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} redeemed the voucher with Merissa Stilwell.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="624b55f122eff465fa2014e1bce188b9bcd28ba548640debeb11f7f4fadd44df",["sourceRaceMask"]="1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
