[5841]={["atomIDs"]={"5841:description:1-33","5841:description:38-177","5841:description:180-277","5841:description:282-340","5841:objective:1-58"},["opening"]="A Coldridge gift voucher named Yori Crackhelm as its recipient. The voucher offered a small companion through the historical Collector's Edition promotion described in the reference.",["pending"]="{actor} would present the Coldridge Valley Gift Voucher to Yori.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} handed the Coldridge Valley Gift Voucher to Yori Crackhelm.",["sourceHash"]="6af56ebeb4d80ffa58717cf1452573f8f67f5e9377d6704335524ddcc1f595d9",["sourceRaceMask"]="68",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
