[5845]={["aftermath"]="Tirion remembered his own oath and hoped his son's redemption might carry his own with it.",["atomIDs"]={"5845:description:1-72","5845:description:77-117","5845:description:119-186","5845:description:191-255","5845:description:260-369","5845:description:371-427","5845:description:432-498","5845:objective:1-113","5845:objective:115-174"},["endingAtomIDs"]={"5845:completion:1-112","5845:completion:117-164"},["opening"]="After Uther's death and the Order's losses, Taelan cast down its standard at Northdale. Tirion sought that tattered symbol to recall the honor his son had renounced.",["pending"]="{actor} planned to recover the fallen standard.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the symbol back to Tirion.",["sourceHash"]="3c5cf5179f3921f883601e9f43d0b9803ea57699b15b8d643b0eb48819d15f54",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5846]={["aftermath"]="Renfray remembered what many island spirits could not and wondered whether answering the request might finally release her.",["atomIDs"]={"5846:description:1-77","5846:description:79-182","5846:description:184-235","5846:description:237-364","5846:description:369-416","5846:description:421-508","5846:objective:1-142"},["endingAtomIDs"]={"5846:completion:1-19","5846:completion:21-133","5846:completion:138-213","5846:completion:218-279","5846:completion:281-328"},["opening"]="A portrait at Caer Darrow preserved Tirion's fondest memory with Karandra and Taelan. He did not know whether painting or artist survived the island's ruin.",["pending"]="{actor} meant to seek the artist or the portrait.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Renfray at Caer Darrow.",["sourceHash"]="bb49f1cbecf5243da752892d6a532d52b8bb7ac49f629e0a2670a6058d239a09",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5847]={["atomIDs"]={"5847:description:1-33","5847:description:38-172","5847:description:175-272","5847:description:277-335","5847:objective:1-67"},["opening"]="Claire was named as Deathknell's recipient for a Collector's Edition gift voucher. The notice promised a small companion in exchange.",["pending"]="{actor} intended to redeem the Deathknell voucher.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the voucher to Claire.",["sourceHash"]="aad59b9e543b2981c8b6f5e3598331669d2f66d95f43cd020d25f38aa69eda1a",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5848]={["aftermath"]="At the sight of the painting, Tirion nearly collapsed and began to sob.",["atomIDs"]={"5848:description:1-15","5848:description:17-93","5848:description:98-184","5848:description:186-241","5848:description:246-369","5848:description:371-448","5848:description:453-485","5848:objective:1-62","5848:objective:64-215","5848:objective:220-258"},["endingAtomIDs"]={"5848:completion:1-52","5848:completion:57-104"},["opening"]="Renfray had concealed Tirion's portrait beneath an image of the twin moons after his trial. The painting still hung deep in what had become the Scarlet Bastion.",["pending"]="{actor} meant to uncover the hidden portrait and return it to Tirion.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Renfray's recovered painting to Tirion.",["sourceHash"]="fdf2906a551283f98f1c0c9c11fd8adc2f8c45137eb56bb57faa5ef665ce2a4e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5861]={["aftermath"]="Myranda recalled her banishment for opposing the verdict against Tirion and agreed to address the wrongs suffered by the family.",["atomIDs"]={"5861:description:1-49","5861:description:51-100","5861:description:105-160","5861:description:162-234","5861:description:239-332","5861:description:337-376","5861:description:378-457","5861:description:459-501","5861:objective:1-60","5861:objective:62-96"},["endingAtomIDs"]={"5861:completion:1-77","5861:completion:79-182","5861:completion:187-257","5861:completion:259-318"},["opening"]="Taelan's Crusaders would attack before accepting Tirion's message. His old confidant at Uther's tomb could provide the deception needed to deliver the collected reminders.",["pending"]="{actor} meant to show Tirion's gift to Myranda.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Myranda with the items.",["sourceHash"]="88684f4b91ab9d42e73d6edb34c5209dbb2967a21dd6b88b90853e38c90c931e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5863]={["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["opening"]="Nomadic Dunemaul ogres had formed a southern compound and spread into Tanaris's old ruins. Andi Lynn wanted their gathering checked, naming Gor'marok's leadership as the key target alongside brutes and enforcers.",["pending"]="{actor} would undertake the assignment against ten Dunemaul Brutes, ten Enforcers and Gor'marok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Andi Lynn's assignment against the specified Dunemaul forces and Gor'marok the Ravager.",["sourceClassMask"]="?",["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5881]={["aftermath"]="Grish welcomed the prospect of relief from the lift and time with his family.",["atomIDs"]={"5881:description:1-47","5881:description:49-109","5881:description:114-237","5881:description:239-381","5881:description:383-452","5881:objective:1-92"},["endingAtomIDs"]={"5881:completion:1-85","5881:completion:87-129","5881:completion:131-137"},["opening"]="Grish's request to visit his family had finally received an answer. Maggran's letter announced a reserve warrior to relieve him at the Great Lift.",["pending"]="{actor} planned to bring Grish the leave message.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the letter at the lift.",["sourceHash"]="2029a965f0a15df78d07d23b7185f74a5621b7b5ea7a25496cf12a8ae4531924",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5882]={["atomIDs"]={"5882:requestItems:1-133","5882:requestItems:135-214","5882:requestItems:216-287","5882:requestItems:292-388"},["coverageQualification"]="BASIC_PROGRESS_EXCHANGE_CONTEXT",["minimumStage"]=3,["objectiveSummary"]="Trade corrupted soul shards for Cenarion plant salve.",["opening"]="A Cenarion beacon revealed corrupted soul shards in tainted beasts. Ground into a reagent, the shards could help make salve for restoring corrupted plants; prepared salve was offered in exchange.",["pending"]="{actor} would gather corrupted soul shards with the beacon.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} exchanged corrupted soul shards for Cenarion plant salve.",["reviewStatus"]="RETAINED_PROGRESS_SOURCE_MARKERS_REVIEWED_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="af576ef9ff2031be000897e0745dd1a72c72ab12cc95da15e0b7acdc7097dd98",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentPlayability","unrecordedPersonalOutcome"}},
