[5926]={["aftermath"]="Turak introduced the calling to preserve balance and the coming lesson in the bear's strength of body and heart.",["atomIDs"]={"5926:description:1-20","5926:description:25-123","5926:description:126-235","5926:description:238-352","5926:description:357-445","5926:objective:1-62"},["endingAtomIDs"]={"5926:completion:1-40","5926:completion:42-50","5926:completion:52-123","5926:completion:128-189","5926:completion:191-248","5926:completion:250-339","5926:completion:341-454","5926:completion:459-473"},["opening"]="Pala had heard Turak's request for the pupil to visit. The patient teacher waited in the Cenarion Circle's main tent on Thunder Bluff's Elder Rise.",["pending"]="{actor} meant to speak with Turak on the Elder Rise.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Turak Runetotem in Thunder Bluff.",["sourceHash"]="c330d5ea47465c39964638b3d1e0f6803514c1a0f6157ba3fbfb9baae4e4ebc2",["sourceRaceMask"]="32",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5927]={["aftermath"]="Turak prepared the pupil for a wider life of service to nature, beginning with the bear's way.",["atomIDs"]={"5927:description:1-20","5927:description:25-123","5927:description:126-235","5927:description:238-352","5927:description:357-445","5927:objective:1-62"},["endingAtomIDs"]={"5927:completion:1-40","5927:completion:42-50","5927:completion:52-123","5927:completion:128-189","5927:completion:191-248","5927:completion:250-339","5927:completion:341-454","5927:completion:459-473"},["opening"]="Gryshka relayed the summons to Turak, an assistant to the Arch Druid. Personal teaching awaited in the main tent on Thunder Bluff's Elder Rise.",["pending"]="{actor} planned to find Turak in Thunder Bluff.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Turak Runetotem on the Elder Rise.",["sourceHash"]="ddae0a772bf7e2b237234e9716bf87733813303ed70cf4481549804866a9dacf",["sourceRaceMask"]="32",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
