[5929]={["aftermath"]="Dendrite sensed new wisdom and strength, and prepared to teach how that strength could be focused.",["atomIDs"]={"5929:description:1-108","5929:description:111-216","5929:description:219-298","5929:description:303-363","5929:description:366-428","5929:description:431-505","5929:objective:1-126","5929:objective:129-197"},["endingAtomIDs"]={"5929:completion:1-78","5929:completion:80-116","5929:completion:118-148","5929:completion:153-226","5929:completion:228-316","5929:completion:318-408"},["opening"]="Dendrite sent the pupil to the ancient bear spirit in northwestern Moonglade. Its teaching was a step every druid took toward understanding the bear's nature.",["pending"]="{actor} planned to learn from the bear spirit and return to Dendrite.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned to Dendrite after receiving the spirit's teaching.",["sourceHash"]="43206825540b8d912890df7d158d2fc53d12605f2fc0b7e1234dcdf4b6566ae2",["sourceRaceMask"]="8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5930]={["aftermath"]="Dendrite recognized the change and turned the lesson toward directing the strength of the bear.",["atomIDs"]={"5930:description:1-108","5930:description:111-216","5930:description:219-298","5930:description:303-363","5930:description:366-428","5930:description:431-505","5930:objective:1-126","5930:objective:129-197"},["endingAtomIDs"]={"5930:completion:1-78","5930:completion:80-116","5930:completion:118-148","5930:completion:153-226","5930:completion:228-316","5930:completion:318-408"},["opening"]="The bear spirit served as mentor to all druids beginning this natural understanding. Dendrite asked the pupil to seek its wisdom before returning to Nighthaven.",["pending"]="{actor} meant to seek the spirit's lesson in northwestern Moonglade.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported back to Dendrite after learning from the bear spirit.",["sourceHash"]="9991d87e3a535db21be8e1a9d7475b8acfd66d27e12a4a39c7224d6e810b714d",["sourceRaceMask"]="32",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5931]={["aftermath"]="Mathrengyl recalled his own intense first meeting with the spirit and prepared the first practical test of its purpose.",["atomIDs"]={"5931:description:1-128","5931:description:131-259","5931:description:262-376","5931:description:381-398","5931:description:401-420","5931:objective:1-81"},["endingAtomIDs"]={"5931:completion:1-17","5931:completion:19-164","5931:completion:166-204","5931:completion:206-236","5931:completion:241-335","5931:completion:337-405","5931:completion:407-469","5931:completion:471-487"},["opening"]="Dendrite sent the pupil back to Mathrengyl to put the lessons into practice. He praised the teacher's balance even near a place where that balance had faltered.",["pending"]="{actor} intended to return to Mathrengyl in Darnassus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Mathrengyl in the Cenarion Enclave.",["sourceHash"]="7d3c7e3b610d43cfa1541b1baa2142d17333e08ae0b503315dcbfbf838fe32cb",["sourceRaceMask"]="8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
