[5941]={["aftermath"]="Chromie said the objects together would raise Darrowshire's spirits and might save Joseph with luck.",["atomIDs"]={"5941:description:1-59","5941:description:62-129","5941:description:131-166","5941:description:171-262","5941:description:265-298","5941:description:303-380","5941:description:383-441","5941:objective:1-49"},["endingAtomIDs"]={"5941:completion:1-23","5941:completion:25-109","5941:completion:114-181"},["opening"]="Carlin had gathered the relics while longing to protect a village already lost. Chromie claimed that another outcome was possible and requested the bundle for her spell.",["pending"]="{actor} intended to bring the gathered relics to Andorhal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the bundle to Chromie.",["sourceHash"]="06e6448ed8c763e0c91d70cf535faf3f4329812ef1ab9d83ddeed7ca013fb110",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
