[5944]={["aftermath"]="Tirion mourned his son's death and declared the Order of the Silver Hand reborn under his leadership.",["atomIDs"]={"5944:description:1-56","5944:description:58-132","5944:description:134-243","5944:description:248-271","5944:description:273-309","5944:description:311-371","5944:description:373-414","5944:description:416-460","5944:description:465-492","5944:description:497-511","5944:objective:1-41"},["endingAtomIDs"]={"5944:completion:1-82","5944:completion:84-131","5944:completion:136-203","5944:completion:208-299","5944:completion:301-387","5944:completion:392-461","5944:completion:463-484","5944:completion:486-501"},["opening"]="Taelan recognized himself as the Grand Crusader's puppet and wanted the dream of standing beside his father to become real. He asked for a departure from Hearthglen rather than more memories of the life he imagined.",["pending"]="{actor} meant to escort Taelan out of Hearthglen.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the outcome of Taelan's escort to Tirion.",["sourceHash"]="e103e67caaf6a3b7ccdf3498990073c50032a82d8296667bb6cf841a2364922f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
