[6282]={["atomIDs"]={"6282:description:1-50","6282:description:52-151","6282:description:156-326","6282:description:331-365","6282:objective:1-152"},["opening"]="Maggran saw the Bloodfury presence as a threat beyond the harpies' own territory. Their numbers obstructed other lives in the mountains he sought to protect.",["pending"]="{actor} planned to confront the four Bloodfury groups.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Maggran's harpy assignment.",["sourceHash"]="17b6a29e8bee89da3dc33dc8ec47d7898386cdaa573409ab40659f861ea44bc4",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6283]={["aftermath"]="Maggran described his anger subsiding and wondered whether he could now turn toward better things.",["atomIDs"]={"6283:description:1-60","6283:description:62-146","6283:description:151-199","6283:description:201-248","6283:description:253-328","6283:description:330-392","6283:objective:1-108"},["endingAtomIDs"]={"6283:completion:1-34","6283:completion:36-63","6283:completion:65-148","6283:completion:150-180","6283:completion:182-237","6283:completion:242-290"},["opening"]="Maggran judged reduced numbers insufficient while the Bloodfury leader remained. He sent the hunt into the Charred Vale's western hills for proof of her defeat.",["pending"]="{actor} meant to bring the Ripper's remains to Maggran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the leader's remains.",["sourceHash"]="b5e5ba5c12d9a88d9964db924d9ed1476cf37466f23a543d01bc96d8d40bb205",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6284]={["aftermath"]="Maggran hoped more travelers could now reach the retreat without fearing the canyon.",["atomIDs"]={"6284:description:1-66","6284:description:71-170","6284:description:175-247","6284:description:249-375","6284:objective:1-73"},["endingAtomIDs"]={"6284:completion:1-17","6284:completion:19-64","6284:completion:66-85","6284:completion:87-144","6284:completion:149-193","6284:completion:198-290"},["opening"]="A warning marked Sishir Canyon as Besseleth's webbed territory. Maggran's bounty sought her fang as evidence against the old predator.",["pending"]="{actor} intended to recover Besseleth's fang.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the fang to Sun Rock Retreat.",["sourceHash"]="79aaf4ef7cc02f9fb698a1608672826f10aed6e63d1de9dba34d80132a2442ba",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6285]={["aftermath"]="Lewis intended to divide the armor among those who needed it immediately.",["atomIDs"]={"6285:description:1-39","6285:description:42-117","6285:description:122-294","6285:description:299-403","6285:description:406-470","6285:objective:1-128"},["bridge"]="Lewis still needed the crate at Sentinel Hill. Dungar's explanation of the gryphon routes left the supply delivery as the purpose of the return, not merely another journey to a familiar landing.",["bridgeFrom"]=6261,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"6285:completion:1-29","6285:completion:31-86","6285:completion:91-104","6285:completion:106-147","6285:completion:149-253"},["opening"]="Lewis still needed the crate at Sentinel Hill. Dungar's explanation of the gryphon routes left the supply delivery as the purpose of the return, not merely another journey to a familiar landing.",["pending"]="{actor} would take Osric's armor shipment to Quartermaster Lewis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the armor crate to Lewis at Sentinel Hill.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="a6747a40321f3aae93d2c38d7ff5a656ce1a891253ad150818afbfd0a46f5c9d",["sourceRaceMask"]="1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6301]={["aftermath"]="Tammra began chanting over the seeds, preparing their promised power for the injured land.",["atomIDs"]={"6301:description:1-73","6301:description:75-133","6301:description:138-198","6301:description:200-316","6301:description:321-411","6301:objective:1-71"},["endingAtomIDs"]={"6301:completion:5-32","6301:completion:34-105","6301:completion:107-149","6301:completion:154-178"},["opening"]="Tammra sought renewal after industry and war damaged Stonetalon. Seeds near Mirkfallon Lake could be imbued with power to hasten their growth.",["pending"]="{actor} planned to gather ten Gaea seeds.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the seeds to Tammra.",["sourceHash"]="bd32aa82a95e16d96d245221f5a39b784ff7330462abe9f10e615bf81813ed10",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
