[6322]={["atomIDs"]={"6322:description:1-55","6322:description:58-169","6322:description:174-228","6322:description:231-277","6322:objective:1-40"},["bridge"]="Gordon packed the supplies into a crate. Getting it back to Silverpine meant taking it to Michael Garrett, the Undercity's bat master.",["bridgeFrom"]=6323,["bridgeReplacesSetup"]=true,["editorialReviewRevision"]="whole-route-review-2-2026-10-26",["opening"]="Gordon packed the Sepulcher's weapons into a crate. Michael could arrange the flight back, provided the destination's bat master was already known.",["pending"]="{actor} intended to bring the supply crate to Michael.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="With {actor}'s delivery, the crate reached Michael.",["sourceHash"]="62cffdd0d1da81962870f77d9eee3366d3231a8ea6d68e68d90096cb0ed6287d",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6323]={["atomIDs"]={"6323:description:1-62","6323:description:65-141","6323:description:146-212","6323:description:215-262","6323:objective:1-125"},["bridge"]="Karos's bats landed in the Undercity's Trade Quarter, where Gordon kept his shop. A small fare would carry the requisition to the dealer who could fill it.",["bridgeFrom"]=6321,["bridgeReplacesSetup"]=true,["editorialReviewRevision"]="whole-route-review-2-2026-10-26",["independentReviewRevision"]="r2-findings-applied-2026-10-26",["opening"]="Karos offered a paid flight to the Undercity. Gordon awaited the requisition in the same Trade Quarter where the bat would land.",["pending"]="{actor} planned to arrange the flight and deliver Podrig's order.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="When {actor} brought the order, Gordon accepted the work as an honor: service to those who served the Dark Lady.",["sourceHash"]="d3e02722ab1b4a4cf8c30715bf58c354e6d363c3143c037668ccdad36c756db8",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6324]={["aftermath"]="Podrig had the replacement weapons his Deathguards needed. They would help keep the guards ready for their next duty.",["atomIDs"]={"6324:description:1-47","6324:description:50-123","6324:description:128-275","6324:description:280-346","6324:description:349-387","6324:objective:1-133"},["bridge"]="Michael could arrange a bat back to Karos, carrying the weapons Podrig awaited.",["bridgeFrom"]=6322,["bridgeReplacesSetup"]=true,["editorialReviewRevision"]="whole-route-review-2-2026-10-26",["endingAtomIDs"]={"6324:completion:1-14","6324:completion:16-85","6324:completion:90-140"},["independentReviewRevision"]="r2-findings-applied-2026-10-26",["opening"]="Michael explained that distant routes required first meeting the local bat master. With Karos known, the weapon crate could return to the Sepulcher.",["pending"]="{actor} meant to fly back and take the crate to Podrig.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="Back at the Sepulcher, {actor} delivered the crate to Podrig.",["sourceHash"]="9290f7c7fcd422d167ec7824201d778d061a4d0d0bb50b2f9d9b0040ab169e13",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
