[6381]={["aftermath"]="Tammra welcomed the new life while placing lasting peace, the company's departure and calmer spirits in the future.",["atomIDs"]={"6381:description:1-88","6381:description:90-127","6381:description:129-222","6381:description:224-299","6381:description:304-380","6381:description:382-410","6381:objective:1-122"},["endingAtomIDs"]={"6381:completion:1-35","6381:completion:37-92","6381:completion:94-213","6381:completion:218-265","6381:completion:270-371"},["opening"]="Tammra's seeds were enchanted, but the damaged vale still needed hands to plant them. Harpies and fire elementals remained among the fertile mounds.",["pending"]="{actor} planned to plant ten seeds and return the remainder.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the planting and returned the unused seeds.",["sourceHash"]="c125f6a167653ad6e317ca685b9b4b5eb45a1ea721ca2e52c5de4e9145090a2b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
